contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 burnValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(burnValue > 0);
        require(address(this).balance >= 0);

        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success = c.burn(burnValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (burnValue > balanceBefore) && (reverted || c.totalSupply() == totalSupplyBefore - burnValue));
    }

    receive() external payable {}
}

