pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnValue) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(burnValue > 0);
        vm.assume(address(this).balance >= 0);
        uint256 balanceBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint256 totalSupplyBefore;
        try c.totalSupply() returns (uint256 __r) { totalSupplyBefore = __r; } catch { return; }
        bool reverted;
        try c.burn(burnValue) returns (bool success) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (burnValue > balanceBefore) && (reverted || c.totalSupply() == totalSupplyBefore - burnValue));
    }

    function testFuzz_run(uint256 burnValue) public {
        _run(burnValue);
    }

    receive() external payable {}
}
